{
  "name": "todomvc-shakedown",
  "version": "0.1.0",
  "private": true,
  "scripts": { "test": "cucumber-js" },
  "devDependencies": { "@cucumber/cucumber": "*", "happy-dom": "*" }
}

const { Given, When, Then } = require('@cucumber/cucumber');
const assert = require('assert');

// ── Helpers ───────────────────────────────────────────────────────────

function todoItems() {
  return Array.from(this.document.querySelectorAll('.todo-list li'));
}

function visibleTodoItems() {
  return todoItems.call(this).filter(
    (li) => li.style.display !== 'none'
  );
}

function nthTodo(n) {
  return todoItems.call(this)[n - 1];
}

function todoTitleAt(n) {
  return nthTodo.call(this, n).querySelector('label').textContent;
}

// ── Background ────────────────────────────────────────────────────────

Given('the app is loaded', function () {
  assert.ok(this.document.querySelector('.todoapp'), 'todoapp should exist');
});

// ── Adding todos ──────────────────────────────────────────────────────

Given('I have added {string}', function (title) {
  const input = this.document.querySelector('.new-todo');
  input.value = title;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, which: 13, bubbles: true }));
});

When('I enter a new todo {string} and press Enter', function (title) {
  const input = this.document.querySelector('.new-todo');
  input.value = title;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, which: 13, bubbles: true }));
});

// ── Inspecting state ──────────────────────────────────────────────────

Then('there is {int} todo', function (count) {
  assert.strictEqual(todoItems.call(this).length, count);
});

Then('there are {int} todos', function (count) {
  assert.strictEqual(todoItems.call(this).length, count);
});

Then('the first todo has title {string}', function (title) {
  assert.strictEqual(todoTitleAt.call(this, 1), title);
});

Then('the input is empty', function () {
  const input = this.document.querySelector('.new-todo');
  assert.strictEqual(input.value, '');
});

Then('the main section is hidden', function () {
  const main = this.document.querySelector('.main');
  assert.strictEqual(main.style.display, 'none');
});

Then('the footer is hidden', function () {
  const footer = this.document.querySelector('.footer');
  assert.strictEqual(footer.style.display, 'none');
});

Then('the main section is visible', function () {
  const main = this.document.querySelector('.main');
  assert.ok(main.style.display !== 'none');
});

Then('the footer is visible', function () {
  const footer = this.document.querySelector('.footer');
  assert.ok(footer.style.display !== 'none');
});

// ── Toggle / complete ─────────────────────────────────────────────────

Given('I have completed todo {int}', function (n) {
  const li = nthTodo.call(this, n);
  const checkbox = li.querySelector('.toggle');
  if (!checkbox.checked) {
    const id = parseInt(li.getAttribute('data-id'), 10);
    this.window.__app.toggleTodo(id);
    this.window.__app.render();
  }
});

When('I click the toggle for todo {int}', function (n) {
  const li = nthTodo.call(this, n);
  const id = parseInt(li.getAttribute('data-id'), 10);
  this.window.__app.toggleTodo(id);
  this.window.__app.render();
});

Then('todo {int} is completed', function (n) {
  const li = nthTodo.call(this, n);
  assert.ok(li.classList.contains('completed'), 'todo should have completed class');
});

Then('todo {int} is not completed', function (n) {
  const li = nthTodo.call(this, n);
  assert.ok(!li.classList.contains('completed'), 'todo should not have completed class');
});

Then('the active count is {int}', function (count) {
  const strong = this.document.querySelector('.todo-count strong');
  assert.strictEqual(parseInt(strong.textContent, 10), count);
});

// ── Toggle all ────────────────────────────────────────────────────────

When('I click toggle-all', function () {
  const toggleAll = this.document.querySelector('.toggle-all');
  const newChecked = !toggleAll.checked;
  toggleAll.checked = newChecked;
  this.window.__app.toggleAll(newChecked);
  this.window.__app.render();
});

Then('all todos are completed', function () {
  const items = todoItems.call(this);
  items.forEach((li) => {
    assert.ok(li.classList.contains('completed'), `todo should be completed: ${li.querySelector('label').textContent}`);
  });
});

Then('all todos are active', function () {
  const items = todoItems.call(this);
  items.forEach((li) => {
    assert.ok(!li.classList.contains('completed'), `todo should be active: ${li.querySelector('label').textContent}`);
  });
});

Given('all todos are checked', function () {
  const items = todoItems.call(this);
  items.forEach((li) => {
    const id = parseInt(li.getAttribute('data-id'), 10);
    const cb = li.querySelector('.toggle');
    if (!cb.checked) {
      // Use the exposed API to toggle
      this.window.__app.toggleTodo(id);
    }
  });
  this.window.__app.render();
});

// ── Destroy ───────────────────────────────────────────────────────────

When('I destroy todo {int}', function (n) {
  const li = nthTodo.call(this, n);
  li.querySelector('.destroy').click();
});

// ── Clear completed ───────────────────────────────────────────────────

When('I click clear-completed', function () {
  this.document.querySelector('.clear-completed').click();
});

Then('the clear-completed button is hidden', function () {
  const btn = this.document.querySelector('.clear-completed');
  assert.ok(btn.style.display === 'none', 'clear-completed should be hidden');
});

Then('the clear-completed button is visible', function () {
  const btn = this.document.querySelector('.clear-completed');
  assert.ok(btn.style.display !== 'none', 'clear-completed should be visible');
});

// ── Editing ───────────────────────────────────────────────────────────

When('I double-click todo {int}', function (n) {
  const li = nthTodo.call(this, n);
  const label = li.querySelector('label');
  label.dispatchEvent(new this.window.Event('dblclick', { bubbles: true }));
});

Then('todo {int} is in editing mode', function (n) {
  const li = nthTodo.call(this, n);
  assert.ok(li.classList.contains('editing'), 'todo should have editing class');
});

Then('todo {int} is not in editing mode', function (n) {
  const li = nthTodo.call(this, n);
  assert.ok(!li.classList.contains('editing'), 'todo should not have editing class');
});

When('I type {string} in the edit field and press Enter', function (title) {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  editInput.value = title;
  editInput.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, which: 13, bubbles: true }));
});

When('I type {string} in the edit field and blur', function (title) {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  editInput.value = title;
  editInput.dispatchEvent(new this.window.Event('blur', { bubbles: true }));
});

When('I clear the edit input and blur', function () {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  editInput.value = '';
  editInput.dispatchEvent(new this.window.Event('blur', { bubbles: true }));
});

When('I type {string} in the edit field and press Escape', function (title) {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  editInput.value = title;
  editInput.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Escape', keyCode: 27, which: 27, bubbles: true }));
});

// ── Counter pluralisation ─────────────────────────────────────────────

Then('the counter text contains {string}', function (text) {
  const countEl = this.document.querySelector('.todo-count');
  assert.ok(countEl.textContent.includes(text), `counter should contain "${text}" but was "${countEl.textContent}"`);
});

// ── Routing ───────────────────────────────────────────────────────────

When('I navigate to {string}', function (hash) {
  this.navigate(hash);
});

Then('there is {int} todo visible', function (count) {
  assert.strictEqual(visibleTodoItems.call(this).length, count);
});

Then('there are {int} todos visible', function (count) {
  assert.strictEqual(visibleTodoItems.call(this).length, count);
});

Then('the first visible todo has title {string}', function (title) {
  const items = visibleTodoItems.call(this);
  assert.ok(items.length > 0, 'should have at least one visible todo');
  assert.strictEqual(items[0].querySelector('label').textContent, title);
});

Then('the {string} filter link is selected', function (name) {
  const map = { all: '#/', active: '#/active', completed: '#/completed' };
  const link = this.document.querySelector(`.filters a[href="${map[name]}"]`);
  assert.ok(link.classList.contains('selected'), `${name} link should be selected`);
});

// ── Persistence ───────────────────────────────────────────────────────

When('I reload the app', function () {
  this.loadApp();
});

const fs = require('node:fs');
const path = require('node:path');
const { setWorldConstructor, Before, After } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');

const ROOT = path.resolve(__dirname, '..', '..');

class AppWorld {
  constructor() {
    this._persistedStorage = {};
  }

  // Load the REAL page and the REAL app. A missing artifact is a loud failure here, not a
  // silently-green suite: the executable tier must exercise the production artifact.
  loadApp() {
    // Preserve localStorage across reloads for persistence tests
    if (this.window && this.window.localStorage) {
      const keys = Object.keys(this.window.localStorage);
      for (const k of keys) {
        this._persistedStorage[k] = this.window.localStorage.getItem(k);
      }
    }
    const indexPath = path.join(ROOT, 'index.html');
    const appPath = path.join(ROOT, 'js', 'app.js');
    if (!fs.existsSync(indexPath))
      throw new Error(`verification support: ${indexPath} does not exist — the app has no page to load`);
    if (!fs.existsSync(appPath))
      throw new Error(`verification support: ${appPath} does not exist — the app has no code to run`);
    const appSource = fs.readFileSync(appPath, 'utf8');
    if (appSource.trim().length === 0)
      throw new Error(`verification support: ${appPath} is empty — there is no application to verify`);

    // disableJavaScriptFileLoading: the harness executes app.js itself as inline source, and a
    // real <script src> under happy-dom attempts a network fetch (ECONNREFUSED, pilot 0.13.64).
    this.window = new Window({
      url: 'http://localhost/',
      settings: { disableJavaScriptFileLoading: true },
    });
    this.document = this.window.document;

    // Restore persisted localStorage into the new window
    for (const [k, v] of Object.entries(this._persistedStorage)) {
      this.window.localStorage.setItem(k, v);
    }

    // The app must EXECUTE, not merely be present. Two things were measured 2026-07-28 and both
    // bit an earlier version of this harness:
    //   1. happy-dom does NOT run scripts the parser sees — neither an appended <script> with
    //      textContent nor one inlined into document.write(). window.eval() DOES run them. An
    //      earlier harness looked green while app.js never ran, because its only assertion
    //      checked that the PAGE had loaded. A weak test hid a broken loader.
    //   2. DOMContentLoaded never fires from write()/close(), so an app that defers its init to
    //      DOMContentLoaded or window.load — the common TodoMVC shape — would never initialise
    //      and the harness would fail CORRECT code. The lifecycle events are dispatched here.
    // disableJavaScriptFileLoading stops the page's own src tag attempting a network fetch
    // (ECONNREFUSED under happy-dom, pilot 0.13.64).
    this.document.write(fs.readFileSync(indexPath, 'utf8'));
    this.document.close();
    this.window.eval(appSource);
    this.document.dispatchEvent(new this.window.Event('DOMContentLoaded', { bubbles: true }));
    this.window.dispatchEvent(new this.window.Event('load'));

    // ROUTING. happy-dom updates location.hash but NEVER fires hashchange — measured
    // 2026-07-28, both by assignment and by clicking an in-page anchor. A TodoMVC router
    // listens for hashchange, so without this the filter/back-button behaviour is
    // UNREACHABLE in this tier: one wave spent seven correction voyages implementing filter
    // links that nothing could ever drive, stuck at 22/29 the whole way. Route the two ways a
    // real browser changes the hash, so routing is exercisable rather than merely present.
    const w = this.window;
    this.document.addEventListener('click', (e) => {
      const a = e.target && e.target.closest ? e.target.closest('a[href^="#"]') : null;
      if (!a) return;
      const next = a.getAttribute('href');
      if (w.location.hash !== next) { w.location.hash = next; w.dispatchEvent(new w.Event('hashchange')); }
    }, true);
    return this.document;
  }

  // Drive the router the way a user's address bar does.
  navigate(hash) {
    if (!this.window) throw new Error('verification support: navigate() before the app was loaded');
    if (this.window.location.hash === hash) return;
    this.window.location.hash = hash;
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  }

  get localStorage() { return this.window.localStorage; }

  // A happy-dom Window holds timers, observers and native buffers; an undisposed one per
  // scenario grows without bound. Measured 2026-07-28: a wave whose own world.js never
  // disposed reached 13.6G RSS across ~45 scenarios and was OOM-killed by the kernel, which
  // ended the suite with a bare "Killed" and no summary line. NODE_OPTIONS
  // --max-old-space-size does NOT prevent this: the growth is outside V8's old space, so the
  // cap bounds the JS heap while the process still takes the box down. Disposal is the fix.
  async disposeApp() {
    const w = this.window;
    if (!w) return;
    this.window = undefined;
    this.document = undefined;
    if (w.happyDOM && typeof w.happyDOM.close === 'function') { await w.happyDOM.close(); return; }
    if (w.happyDOM && typeof w.happyDOM.abort === 'function') { await w.happyDOM.abort(); return; }
    if (typeof w.close === 'function') w.close();
  }
}

setWorldConstructor(AppWorld);

// Every scenario gets the real app. No scenario can pass without one.
Before(function () { this.loadApp(); });
// ...and every scenario gives it back.
After(async function () { await this.disposeApp(); });

(function () {
	'use strict';

	var ENTER_KEY = 13;
	var ESCAPE_KEY = 27;
	var STORAGE_KEY = 'todos-vanillajs';

	// ── Model ──────────────────────────────────────────────────────────────

	var todos = [];
	var nextId = 1;

	function save() {
		localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
	}

	function load() {
		try {
			var raw = localStorage.getItem(STORAGE_KEY);
			if (raw) {
				todos = JSON.parse(raw);
				// restore nextId above any existing ids
				for (var i = 0; i < todos.length; i++) {
					if (todos[i].id >= nextId) nextId = todos[i].id + 1;
				}
			}
		} catch (e) {
			todos = [];
		}
	}

	function createTodo(title) {
		var todo = { id: nextId++, title: title, completed: false };
		todos.push(todo);
		save();
		return todo;
	}

	function destroyTodo(id) {
		todos = todos.filter(function (t) { return t.id !== id; });
		save();
	}

	function toggleTodo(id) {
		for (var i = 0; i < todos.length; i++) {
			if (todos[i].id === id) {
				todos[i].completed = !todos[i].completed;
				break;
			}
		}
		save();
	}

	function toggleAll(checked) {
		for (var i = 0; i < todos.length; i++) {
			todos[i].completed = checked;
		}
		save();
	}

	function clearCompleted() {
		todos = todos.filter(function (t) { return !t.completed; });
		save();
	}

	function updateTodo(id, title) {
		for (var i = 0; i < todos.length; i++) {
			if (todos[i].id === id) {
				todos[i].title = title;
				break;
			}
		}
		save();
	}

	function getFilteredTodos(route) {
		if (route === '#/active') {
			return todos.filter(function (t) { return !t.completed; });
		}
		if (route === '#/completed') {
			return todos.filter(function (t) { return t.completed; });
		}
		return todos.slice();
	}

	// ── DOM helpers ────────────────────────────────────────────────────────

	var newTodoInput = document.querySelector('.new-todo');
	var todoList = document.querySelector('.todo-list');
	var mainSection = document.querySelector('.main');
	var footer = document.querySelector('.footer');
	var toggleAllCheckbox = document.querySelector('.toggle-all');
	var todoCount = document.querySelector('.todo-count');
	var clearCompletedBtn = document.querySelector('.clear-completed');
	var filterLinks = document.querySelectorAll('.filters a');

	function createTodoElement(todo) {
		var li = document.createElement('li');
		li.setAttribute('data-id', todo.id);
		if (todo.completed) li.classList.add('completed');

		var div = document.createElement('div');
		div.className = 'view';

		var checkbox = document.createElement('input');
		checkbox.className = 'toggle';
		checkbox.type = 'checkbox';
		checkbox.checked = todo.completed;

		var label = document.createElement('label');
		label.textContent = todo.title;

		var destroyBtn = document.createElement('button');
		destroyBtn.className = 'destroy';

		var editInput = document.createElement('input');
		editInput.className = 'edit';
		editInput.value = todo.title;

		div.appendChild(checkbox);
		div.appendChild(label);
		div.appendChild(destroyBtn);

		li.appendChild(div);
		li.appendChild(editInput);
		return li;
	}

	// ── Rendering ──────────────────────────────────────────────────────────

	var currentRoute = '#/';

	function render() {
		var filtered = getFilteredTodos(currentRoute);

		// Clear existing list
		todoList.innerHTML = '';

		// Append todo elements
		for (var i = 0; i < filtered.length; i++) {
			todoList.appendChild(createTodoElement(filtered[i]));
		}

		// Show/hide main and footer
		var hasTodos = todos.length > 0;
		mainSection.style.display = hasTodos ? '' : 'none';
		footer.style.display = hasTodos ? '' : 'none';

		// Update count
		var activeCount = todos.filter(function (t) { return !t.completed; }).length;
		todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' +
			(activeCount === 1 ? 'item' : 'items') + ' left';

		// Update toggle-all
		toggleAllCheckbox.checked = todos.length > 0 && todos.every(function (t) { return t.completed; });

		// Show/hide clear completed
		var hasCompleted = todos.some(function (t) { return t.completed; });
		clearCompletedBtn.style.display = hasCompleted ? '' : 'none';

		// Update filter links
		for (var j = 0; j < filterLinks.length; j++) {
			var link = filterLinks[j];
			if (link.getAttribute('href') === currentRoute) {
				link.classList.add('selected');
			} else {
				link.classList.remove('selected');
			}
		}
	}

	// ── Routing ────────────────────────────────────────────────────────────

	function getRoute() {
		var hash = window.location.hash || '#/';
		return hash;
	}

	function onHashChange() {
		currentRoute = getRoute();
		render();
	}

	// ── Event handlers ─────────────────────────────────────────────────────

	// New todo input
	newTodoInput.addEventListener('keydown', function (e) {
		if (e.which !== ENTER_KEY) return;
		var val = newTodoInput.value.trim();
		if (!val) return;
		createTodo(val);
		newTodoInput.value = '';
		render();
	});

	// Toggle all
	toggleAllCheckbox.addEventListener('change', function () {
		toggleAll(toggleAllCheckbox.checked);
		render();
	});

	// Clear completed
	clearCompletedBtn.addEventListener('click', function () {
		clearCompleted();
		render();
	});

	// Delegated events on the todo list
	todoList.addEventListener('change', function (e) {
		// Toggle individual todo
		if (e.target.classList.contains('toggle')) {
			var li = e.target.closest('li');
			var id = parseInt(li.getAttribute('data-id'), 10);
			toggleTodo(id);
			render();
		}
	});

	todoList.addEventListener('click', function (e) {
		// Destroy button
		if (e.target.classList.contains('destroy')) {
			var li = e.target.closest('li');
			var id = parseInt(li.getAttribute('data-id'), 10);
			destroyTodo(id);
			render();
		}
	});

	todoList.addEventListener('dblclick', function (e) {
		// Activate editing mode
		if (e.target.tagName === 'LABEL') {
			var li = e.target.closest('li');
			li.classList.add('editing');
			var editInput = li.querySelector('.edit');
			editInput.value = e.target.textContent;
			editInput.focus();
		}
	});

	todoList.addEventListener('keydown', function (e) {
		if (!e.target.classList.contains('edit')) return;
		if (e.which === ENTER_KEY) {
			e.target.blur();
		}
		if (e.which === ESCAPE_KEY) {
			var li = e.target.closest('li');
			var id = parseInt(li.getAttribute('data-id'), 10);
			var todo = todos.find(function (t) { return t.id === id; });
			if (todo) e.target.value = todo.title;
			e.target.blur();
		}
	});

	todoList.addEventListener('blur', function (e) {
		if (!e.target.classList.contains('edit')) return;
		var li = e.target.closest('li');
		var id = parseInt(li.getAttribute('data-id'), 10);
		var val = e.target.value.trim();
		if (val) {
			updateTodo(id, val);
		} else {
			destroyTodo(id);
		}
		li.classList.remove('editing');
		render();
	}, true);

	// Filter links (handled by delegated click via hash change)
	for (var i = 0; i < filterLinks.length; i++) {
		filterLinks[i].addEventListener('click', function () {
			currentRoute = this.getAttribute('href');
			render();
		});
	}

	// ── Init ───────────────────────────────────────────────────────────────

	load();
	currentRoute = getRoute();
	render();

	window.addEventListener('hashchange', onHashChange);

	// Expose internals for testing
	window.__app = {
		todos: todos,
		toggleTodo: toggleTodo,
		toggleAll: toggleAll,
		render: render
	};
})();

function render() {
	var filtered = getFilteredTodos(currentRoute);

	// Clear existing list
	todoList.innerHTML = '';

	// Append todo elements
	for (var i = 0; i < filtered.length; i++) {
		todoList.appendChild(createTodoElement(filtered[i]));
	}

	// Show/hide main and footer
	var hasTodos = todos.length > 0;
	mainSection.style.display = hasTodos ? '' : 'none';
	footer.style.display = hasTodos ? '' : 'none';

	// Update count
	var activeCount = todos.filter(function (t) { return !t.completed; }).length;
	todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' +
		(activeCount === 1 ? 'item' : 'items') + ' left';

	// Update toggle-all
	toggleAllCheckbox.checked = todos.length > 0 && todos.every(function (t) { return t.completed; });

	// Show/hide clear completed
	var hasCompleted = todos.some(function (t) { return t.completed; });
	clearCompletedBtn.style.display = hasCompleted ? '' : 'none';

	// Update filter links
	for (var j = 0; j < filterLinks.length; j++) {
		var link = filterLinks[j];
		if (link.getAttribute('href') === currentRoute) {
			link.classList.add('selected');
		} else {
			link.classList.remove('selected');
		}
	}
}

	if (route === '#/completed') {
		return todos.filter(function (t) { return t.completed; });
	}
	return todos.slice();
}

// ── DOM helpers ────────────────────────────────────────────────────────

var newTodoInput = document.querySelector('.new-todo');
var todoList = document.querySelector('.todo-list');
var mainSection = document.querySelector('.main');
var footer = document.querySelector('.footer');
var toggleAllCheckbox = document.querySelector('.toggle-all');
var todoCount = document.querySelector('.todo-count');
var clearCompletedBtn = document.querySelector('.clear-completed');
var filterLinks = document.querySelectorAll('.filters a');

function createTodoElement(todo) {
	var li = document.createElement('li');
	li.setAttribute('data-id', todo.id);
	if (todo.completed) li.classList.add('completed');

	var div = document.createElement('div');
	div.className = 'view';

